head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
//★Wcraft guide★ include부분 주석처리 -> include("../RexServer/rexscript/rexpert.js");
//★Wcraft guide★ include부분 주석처리 -> include("../RexServer/rexscript/rexpert_properties.js");
scwin.vScrenID = "ULDSTF40601.xml";
scwin.notiId;
scwin.vMakId = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.setMainHeader = function() {
    dts_certificateApprove.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LISTCERT_INOUT";
    dts_certificateApprove.Reset();
    dts_certificateApprove.insertRow();
    dts_useContn.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LISTCERT_USE_TP_INOUT";
    dts_useContn.Reset();
};
scwin.fn_searchCode = function() {
    /*
    01443 - 상장증명서용도구분코드
    */
    var arrCid = [{
        cid: "LIST_CERT_USE_TP_CD",
        cnm: "cmb_LIST_CERT_USE_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='LIST_CERT_USE_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                if (dts_Cod.getCellData(j, "VALUE") != '99') {
                    //담당자요구로 기타 삭제(2008.11.12)
                    strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
                }
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_read = function() {
    trs_Read.Action = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readCertificate&CONTN_ID=" + scwin.notiId;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_readCertificateApprove,O:pOutput2=dts_useContn)";
    trs_Read.Post();
};
scwin.fn_save = function() {
    if ($c.stf.getObjectValue(txb_COM_NM) == "") {
        $c.win.alert("[회사코드/명]를 선택해주세요.");
        txb_COM_NM.focus();
        return;
    }
    if ($c.stf.getObjectValue(rdo_LIST_CERT_TP_CD) == "") {
        $c.win.alert("[상장증명서구분]을 선택해주세요.");
        rdo_LIST_CERT_TP_CD.focus();
        return;
    }
    if ($c.stf.getObjectValue(rdo_KORENG_TP_CD) == "") {
        $c.win.alert("[한글영문구분]을 선택해주세요.");
        rdo_KORENG_TP_CD.focus();
        return;
    }
    if (dts_useContn.getTotalRow() == 0) {
        $c.win.alert("[용도구분]을 1개 이상 추가해주세요.");
        cmb_LIST_CERT_USE_TP_CD.focus();
        return;
    }
    var rtn = confirm('내용을 등록 하시겠습니까?');
    if (rtn == 1) {
        dts_certificateApprove.setCellData(dts_certificateApprove.getRowPosition(), "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
        dts_certificateApprove.setCellData(dts_certificateApprove.getRowPosition(), "MKT_ID", scwin.vMakId);
        dts_certificateApprove.setCellData(dts_certificateApprove.getRowPosition(), "CERT_APPL_USR_ID", js_emp_no);
        dts_certificateApprove.setCellData(dts_certificateApprove.getRowPosition(), "LIST_CERT_PROCS_STAT_CD", "1"); //등록시 접수 '1'로 세팅

        trs_Save.Action = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=createCertificate";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_certificateApprove,I:pInput2=dts_useContn)";
        trs_Save.Post();
    }
};
scwin.fn_approve = function() {
    var rtn = confirm('증명서발급을 승인처리 하시겠습니까?');
    if (rtn == 1) {
        var vStatCd = '9'; //승인
        scwin.fn_trs(vStatCd);
    }
};
scwin.fn_reject = function() {
    var rtn = confirm('증명서발급을 거부처리 하시겠습니까?');
    if (rtn == 1) {
        var vStatCd = '5'; //거부
        scwin.fn_trs(vStatCd);
    }
};
scwin.fn_trs = function(gStatCd) {
    dts_readCertificateApprove.setCellData(1, "LIST_CERT_PROCS_STAT_CD", gStatCd);
    dts_readCertificateApprove.setCellData(1, "ISU_CHRG_EMP_NO", js_emp_no);
    var url = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=approveCertificate";
    trs_Update.Action = encodeURI(url);
    trs_Update.KeyValue = "JSP(I:pInput=dts_readCertificateApprove)";
    trs_Update.Post();
};
scwin.fn_print = function(listCertApplId, bycertSeq, ldMktTpCd, korengTpCd, listCertTpCd, listNo, stkcertDelistDd) {
    var pdf_rptname;
    var dataUrl = "/CertificateApprove.do?method=searchListCertificate&outputMessageId=LISTCERT_REPORT_INOUT" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq;
    //상장증명서
    if (listCertTpCd == "1") {
        if (ldMktTpCd == "1") {
            //유가증권시장
            if (korengTpCd == "1") {
                //한글증명서
                dataUrl = dataUrl + "&reportDiv=1";
                pdf_rptname = "RLDSTF10005";
            } else {
                //영문증명서
                dataUrl = dataUrl + "&reportDiv=2";
                pdf_rptname = "RLDSTF10006";
            }
        } else if (ldMktTpCd == "2") {
            //코스닥시장
            if (korengTpCd == "1") {
                //한글증명서
                dataUrl = dataUrl + "&reportDiv=3";
                pdf_rptname = "RLDSTF10013";
            } else {
                //영문증명서
                dataUrl = dataUrl + "&reportDiv=4";
                pdf_rptname = "RLDSTF10014";
            }
        } else {
            //코넥스시장
            if (korengTpCd == "1") {
                //한글증명서
                dataUrl = dataUrl + "&reportDiv=3";
                pdf_rptname = "RLDSTF10037";
            } else {
                //영문증명서
                dataUrl = dataUrl + "&reportDiv=4";
                pdf_rptname = "RLDSTF10038";
            }
        }
    } else {
        //상장폐지증명서

        if (ldMktTpCd == "1") {
            //유가

            if (korengTpCd == "1") {
                //한글증명서
                dataUrl = dataUrl + "&reportDiv=5";
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10009";
                } else {
                    pdf_rptname = "RLDSTF10016";
                }
            } else {
                //영문증명서
                dataUrl = dataUrl + "&reportDiv=6";
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10010";
                } else {
                    pdf_rptname = "RLDSTF10019";
                }
            }
        } else if (ldMktTpCd == "2") {
            //코스닥

            if (korengTpCd == "1") {
                //한글증명서
                dataUrl = dataUrl + "&reportDiv=5";
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10011";
                } else {
                    pdf_rptname = "RLDSTF10018";
                }
            } else {
                //영문증명서
                dataUrl = dataUrl + "&reportDiv=6";
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10012";
                } else {
                    pdf_rptname = "RLDSTF10017";
                }
            }
        } else {
            //코넥스
            if (korengTpCd == "1") {
                //한글증명서
                dataUrl = dataUrl + "&reportDiv=5";
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10011";
                } else {
                    pdf_rptname = "RLDSTF10018";
                }
            } else {
                //영문증명서
                dataUrl = dataUrl + "&reportDiv=6";
                if (stkcertDelistDd > '20050127') {
                    pdf_rptname = "RLDSTF10012";
                } else {
                    pdf_rptname = "RLDSTF10017";
                }
            }
        }
    }
    dts_Report.DataID = encodeURI(dataUrl);
    dts_Report.Reset();

    //set data report --> target (DB컬럼명과 Report 컬럼명이 다름)
    var dtsFormatArr = ["certSeq:CERT_SEQ:STRING", "comNm:COM_NM:STRING", "listCmstkShrs:LIST_CMSTK_SHRS:DECIMAL", "listPrefstkShrs:LIST_PREFSTK_SHRS:DECIMAL", "parval:PARVAL:STRING", "cap:CAP:DECIMAL", "currIsoCd:CURR_ISO_CD:STRING", "ldMktTpCd:LD_MKT_TP_CD:STRING", "listDd:LIST_DD:STRING", "listCertUseContn:LIST_CERT_USE_CONTN:STRING", "today:TODAY:STRING", "ceoNm:CEO_NM:STRING", "indNm:IND_NM:STRING", "listNo:LIST_NO:DECIMAL", "stkcertDelistDd:STKCERT_DELIST_DD:STRING"];


    //set dataFormat
    var dataFormatArr = [];
    if (korengTpCd == "1") {
        //한글증명서
        dataFormatArr = ["LIST_CMSTK_SHRS:FormatNumberEx", "LIST_PREFSTK_SHRS:FormatNumberEx", "CAP:FormatNumberEx", "LIST_DD:FormatDateEx3", "STKCERT_DELIST_DD:FormatDateEx3", "TODAY:FormatDateEx3"];
    } else {
        if (listCertTpCd == "1" && ldMktTpCd == "1") {
            //상장증명서 && 유가 && 영문증명서
            dataFormatArr = ["LIST_CMSTK_SHRS:FormatNumberEx", "LIST_PREFSTK_SHRS:FormatNumberEx", "CAP:FormatNumberEx", "LIST_DD:FormatDateEngEx1", "STKCERT_DELIST_DD:FormatDateEngEx1", "TODAY:FormatDateEngEx1"]; //YYYYMMDD --> YYYY. MM. DD

        } else {
            dataFormatArr = ["LIST_CMSTK_SHRS:FormatNumberEx", "LIST_PREFSTK_SHRS:FormatNumberEx", "CAP:FormatNumberEx", "LIST_DD:FormatDateEngEx3", "STKCERT_DELIST_DD:FormatDateEngEx3", "TODAY:FormatDateEngEx3"]; //MMDDYYYY --> MM.DD.YYYY

        }
    }
    var jsonData = $c.rpt.fn_make_dtsToJson3_wdf(dtsFormatArr, dts_Report, dataFormatArr);

    //		alert(JSON.stringify(jsonData));
    var userParam = [{
        uid: "jsonData",
        unm: jsonData
    }];

    //PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
};


/* ASIS rexpert-bak 2018-04-03 */
scwin.fn_print_old = function(listCertApplId, bycertSeq, ldMktTpCd, korengTpCd, listCertTpCd, listNo, stkcertDelistDd) {
    var rexName;
    var dataType = "XML";
    var dataLocation = "";
    var dataXPath = "main/rpt1";
    var svrGubun = js_svrGubun; // 서버구분(session.js정보)

    //상장증명서
    if (listCertTpCd == "1") {
        if (ldMktTpCd == "1") {
            //유가증권시장
            if (korengTpCd == "1") {
                //한글증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=1";
                rexName = "RLDFIL00005";
            } else {
                //영문증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=2";
                rexName = "RLDFIL00006";
            }
        } else if (ldMktTpCd == "2") {
            //코스닥시장
            if (korengTpCd == "1") {
                //한글증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=3";
                rexName = "RLDFIL00013";
            } else {
                //영문증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=4";
                rexName = "RLDFIL00014";
            }
        } else {
            //코넥스시장
            if (korengTpCd == "1") {
                //한글증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=3";
                rexName = "RLDFIL00037";
            } else {
                //영문증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=4";
                rexName = "RLDFIL00038";
            }
        }
    } else {
        //상장폐지증명서

        if (ldMktTpCd == "1") {
            //유가

            if (korengTpCd == "1") {
                //한글증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=5";
                if (stkcertDelistDd > '20050127') {
                    rexName = "RLDFIL00009";
                } else {
                    rexName = "RLDFIL00016";
                }
            } else {
                //영문증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=6";
                if (stkcertDelistDd > '20050127') {
                    rexName = "RLDFIL00010";
                } else {
                    rexName = "RLDFIL00019";
                }
            }
        } else if (ldMktTpCd == "2") {
            //코스닥

            if (korengTpCd == "1") {
                //한글증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=5";
                if (stkcertDelistDd > '20050127') {
                    rexName = "RLDFIL00011";
                } else {
                    rexName = "RLDFIL00018";
                }
            } else {
                //영문증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=6";
                if (stkcertDelistDd > '20050127') {
                    rexName = "RLDFIL00012";
                } else {
                    rexName = "RLDFIL00017";
                }
            }
        } else {
            //코넥스
            if (korengTpCd == "1") {
                //한글증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=5";
                if (stkcertDelistDd > '20050127') {
                    rexName = "RLDFIL00011";
                } else {
                    rexName = "RLDFIL00018";
                }
            } else {
                //영문증명서
                dataLocation = "/CertificateApprove.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=searchListCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=6";
                if (stkcertDelistDd > '20050127') {
                    rexName = "RLDFIL00012";
                } else {
                    rexName = "RLDFIL00017";
                }
            }
        }
    }

    // 인쇄 미리보기
    $c.rpt.fn_PrintPreView(rexName, dataType, dataLocation, dataXPath, svrGubun);
};
scwin.btn_print_onclick = function() {
    var listCertApplId = "";
    var bycertSeq = "";
    var ldMktTpCd = "";
    var korengTpCd = "";
    var listCertTpCd = "";
    var stkcertDelistDd = "";
    var listNo = "";
    listCertApplId = dts_useContn.getCellData(dts_useContn.getRowPosition(), "LIST_CERT_APPL_ID");
    bycertSeq = dts_useContn.getCellData(dts_useContn.getRowPosition(), "BYCERT_SEQ");
    if (dts_readCertificateApprove.getCellData(dts_readCertificateApprove.getRowPosition(), "MKT_NM") == "기타") {
        ldMktTpCd = "9";
    } else if (dts_readCertificateApprove.getCellData(dts_readCertificateApprove.getRowPosition(), "MKT_NM") == "유가") {
        ldMktTpCd = "1";
    } else if (dts_readCertificateApprove.getCellData(dts_readCertificateApprove.getRowPosition(), "MKT_NM") == "코스닥") {
        ldMktTpCd = "2";
    } else if (dts_readCertificateApprove.getCellData(dts_readCertificateApprove.getRowPosition(), "MKT_NM") == "코넥스") {
        ldMktTpCd = "6"; //코넥스시장

    }
    korengTpCd = dts_readCertificateApprove.getCellData(dts_readCertificateApprove.getRowPosition(), "KORENG_TP_CD");
    listCertTpCd = dts_readCertificateApprove.getCellData(dts_readCertificateApprove.getRowPosition(), "LIST_CERT_TP_CD");
    listNo = dts_readCertificateApprove.getCellData(dts_readCertificateApprove.getRowPosition(), "LIST_DD");
    stkcertDelistDd = dts_readCertificateApprove.getCellData(dts_readCertificateApprove.getRowPosition(), "STKCERT_DELIST_DD");

    //alert('[listNo]'+listNo);
    //alert('[stkcertDelistDd]'+stkcertDelistDd);
    //alert('[dts_readCertificateApprove]'+dts_readCertificateApprove.Text);

    scwin.fn_print(listCertApplId, bycertSeq, ldMktTpCd, korengTpCd, listCertTpCd, listNo, stkcertDelistDd);
};
scwin.dts_readCertificateApprove_OnLoadError = function() {
    $c.stf.alert_error(dts_readCertificateApprove);
};
scwin.dts_useContn_OnLoadError = function() {
    $c.stf.alert_error(dts_useContn);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    $c.win.alert(trs_Save.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    $c.win.alert(trs_Update.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.btn_save_onclick = function() {
    scwin.fn_save();
};
scwin.btn_approve_onclick = function() {
    scwin.fn_approve();
};
scwin.btn_reject_onclick = function() {
    scwin.fn_reject();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    scwin.vMakId = js_market;
    if (scwin.vMakId == '1') {
        $c.stf.setObjectValue(txb_MKT_NM, "유가증권시장");
    } else if (scwin.vMakId == '2') {
        $c.stf.setObjectValue(txb_MKT_NM, "코스닥증권시장");
    } else if (scwin.vMakId == '6') {
        $c.stf.setObjectValue(txb_MKT_NM, "코넥스증권시장");
    } else {
        $c.stf.setObjectValue(txb_MKT_NM, "-");
    }
};
scwin.btn_lineadd_onclick = function() {
    if (cmb_LIST_CERT_USE_TP_CD.BindColVal != "") {
        for (i = 1; i <= dts_useContn.getTotalRow(); i++) {
            if (dts_useContn.getCellData(i, "LIST_CERT_USE_TP_CD") == $c.stf.getObjectValue(cmb_LIST_CERT_USE_TP_CD)) {
                $c.win.alert("동일한 용도구분은 추가하실수 없습니다.");
                return;
            }
        }
        dts_useContn.insertRow();
        dts_useContn.setCellData(dts_useContn.getRowPosition(), "LIST_CERT_USE_TP_CD", $c.stf.getObjectValue(cmb_LIST_CERT_USE_TP_CD));
        dts_useContn.setCellData(dts_useContn.getRowPosition(), "LIST_CERT_USE_CONTN", $c.stf.fn_getComboTextValue(cmb_LIST_CERT_USE_TP_CD));
    } else {
        return;
    }
};
scwin.btn_linedelete_onclick = function() {
    if (scwin.notiId == "input") {
        $c.cp.removeRow(dts_useContn, dts_useContn.getRowPosition());
    }
};
scwin.gform_onload = function() {
    //MoveCenterOfParent(); //팝업화면중앙으로 이동..

    $c.cm.PanelToGroupBox(panel_Top);
    getId = $c.frame.path("../").fn_getId;
    scwin.notiId = getId();
    scwin.fn_searchCode();
    if (scwin.notiId != "input") {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        scwin.fn_read(); /*ORG SRC: dts_readCertificateApprove.UserStatus(1) = 1;*/ X = 1;
        $c.stf.showObj(pan_save, false);
        $c.stf.showObj(panel_print, true);
        $c.stf.showObj(pan_COM_NM, false);
        rdo_LIST_CERT_TP_CD.setDisabled(true);
        rdo_KORENG_TP_CD.setDisabled(true);
        cmb_LIST_CERT_USE_TP_CD.setDisabled(true);
        if (dts_readCertificateApprove.getCellData(dts_readCertificateApprove.getRowPosition(), "LIST_CERT_PROCS_STAT_CD") == "1") {
            $c.stf.showObj(pan_approve, true);
        } else {
            $c.stf.showObj(pan_approve, false);
        }
    } else {
        $c.stf.showObj(pan_approve, false);
        $c.stf.showObj(panel_print, false);
        txb_CERT_APPL_USR_NM.setValue(js_emp_nm);
        edt_CERT_APPL_DDTM.setValue($c.ut.cGetToday("yyyymmddhhmmss"));
        scwin.setMainHeader();
    }
};
